export type ButtonVariant = "primary" | "secondary" | "ghost" | "outline";
export type ButtonSize = "sm" | "md" | "lg" | "icon";
export type ButtonState = "idle" | "loading" | "success" | "error";

export const buttonVariants = [
	"primary",
	"secondary",
	"ghost",
	"outline",
] as const satisfies readonly ButtonVariant[];
export const buttonSizes = ["sm", "md", "lg", "icon"] as const satisfies readonly ButtonSize[];

type ButtonStyle = {
	variant?: ButtonVariant;
	size?: ButtonSize;
	/** One of the special looks. `metallic` ignores `variant`. */
	look?: "magnetic" | "metallic";
};

/**
 * The class list for a Button. The look lives in `button.css` (your global CSS, when installed from
 * the registry): tones, sizes, press, hover, ripple and label swaps. So React, Solid and plain HTML
 * all get the same button from these names:
 *
 *   <button class="rx-btn rx-btn-primary rx-btn-md">Save</button>
 */
export function buttonClass({ variant = "primary", size = "md", look }: ButtonStyle = {}) {
	const tone = look === "metallic" ? "rx-btn-metal" : `rx-btn-${variant}`;
	return `rx-btn ${tone} rx-btn-${size}${look === "magnetic" ? " rx-btn-magnet" : ""}`;
}

/** Class names for the parts inside a Button, for markup written by hand. */
export const buttonParts = {
	/** Holds the ripples; clipped to the button's shape. */
	ripples: "rx-btn-ripples",
	ripple: "rx-btn-ripple",
	/** An icon that widens in and out next to the label. Shown with `data-shown`. */
	slot: "rx-btn-slot",
	/** The built-in status glyphs: add `data-glyph="spinner" | "check" | "cross"`. */
	glyph: "rx-btn-glyph",
	/** The label box. Its width follows `--_btn-text-w` so a label swap resizes smoothly. */
	text: "rx-btn-text",
	/** One label. `data-enter` rolls it in letter by letter, `data-exit` rolls it out. */
	label: "rx-btn-label",
	letter: "rx-btn-letter",
	srOnly: "rx-btn-sr",
	/** The chrome rim, its sweeping highlight, the face over them and the face's bevel. */
	metalRim: "rx-btn-metal-rim",
	metalSheen: "rx-btn-metal-sheen",
	metalFace: "rx-btn-metal-face",
	metalBevel: "rx-btn-metal-bevel",
	content: "rx-btn-content",
} as const;

"use client";

import type { AnchorHTMLAttributes, ButtonHTMLAttributes, Ref } from "react";
import type { ButtonSize } from "./button.styles";
import { type ButtonLookProps, useButtonLook } from "./use-button";

/** An icon-only button has no visible text, so its type asks for an accessible name. */
export type IconOnly<P> =
	| (P & { size?: Exclude<ButtonSize, "icon"> })
	| (P & { size: "icon"; "aria-label": string });

export type ButtonProps = IconOnly<
	Omit<ButtonHTMLAttributes<HTMLButtonElement>, "size"> &
		Omit<ButtonLookProps, "size"> & { ref?: Ref<HTMLButtonElement> }
>;

/**
 * A native `<button>`. Hover grows it a touch on devices with a real pointer, pressing springs it
 * down to `pressScale`, and `ripple` spreads a disc from the press. Icons are children, so the
 * package depends on no icon set.
 */
export function Button({
	variant,
	size,
	pressScale,
	ripple,
	className,
	style,
	onPointerDown,
	type = "button",
	children,
	ref,
	...rest
}: ButtonProps) {
	const look = useButtonLook<HTMLButtonElement>(
		{ variant, size, pressScale, ripple },
		{ className, style, onPointerDown },
	);
	return (
		<button
			{...rest}
			ref={ref}
			type={type}
			className={look.className}
			style={look.style}
			onPointerDown={look.onPointerDown}
		>
			{look.ripples}
			{children}
		</button>
	);
}

export type ButtonLinkProps = IconOnly<
	Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "size"> &
		Omit<ButtonLookProps, "size"> & { ref?: Ref<HTMLAnchorElement> }
>;

/** A link that looks like a Button. It navigates, so it stays an `<a>` for the browser and readers. */
export function ButtonLink({
	variant,
	size,
	pressScale,
	ripple,
	className,
	style,
	onPointerDown,
	children,
	ref,
	...rest
}: ButtonLinkProps) {
	const look = useButtonLook<HTMLAnchorElement>(
		{ variant, size, pressScale, ripple },
		{ className, style, onPointerDown },
	);
	return (
		<a
			{...rest}
			ref={ref}
			className={look.className}
			style={look.style}
			onPointerDown={look.onPointerDown}
		>
			{look.ripples}
			{children}
		</a>
	);
}

"use client";

import type { PointerEvent } from "react";
import { Button, type ButtonProps } from "./button";
import { magneticOffset } from "./magnetic";
import { cn } from "@/lib/utils";

export type MagneticButtonProps = ButtonProps & {
	/** How strongly the button leans toward the pointer, 0 to 1. Default 0.25. */
	strength?: number;
};

/**
 * A Button that leans toward a mouse pointer and springs back when it leaves. The pointer only
 * writes two CSS variables; the CSS `translate` transition on the magnetic spring does the motion,
 * and turns itself off for touch, reduced motion and `data-motion="off"`.
 */
export function MagneticButton({
	strength = 0.25,
	onPointerMove,
	onPointerLeave,
	className,
	...rest
}: MagneticButtonProps) {
	const follow = (event: PointerEvent<HTMLButtonElement>) => {
		onPointerMove?.(event);
		if (event.pointerType !== "mouse") return;
		const node = event.currentTarget;
		// Measure without the current lean, or the button would chase its own offset.
		const rect = node.getBoundingClientRect();
		const now = currentOffset(node);
		const { x, y } = magneticOffset(
			// DOMRect fields are getters, so they are copied by name, not spread.
			{ left: rect.left - now.x, top: rect.top - now.y, width: rect.width, height: rect.height },
			event.clientX,
			event.clientY,
			strength,
		);
		node.style.setProperty("--_btn-mx", `${x}px`);
		node.style.setProperty("--_btn-my", `${y}px`);
	};

	const release = (event: PointerEvent<HTMLButtonElement>) => {
		onPointerLeave?.(event);
		event.currentTarget.style.removeProperty("--_btn-mx");
		event.currentTarget.style.removeProperty("--_btn-my");
	};

	return (
		<Button
			{...(rest as ButtonProps)}
			className={cn("rx-btn-magnet", className)}
			onPointerMove={follow}
			onPointerLeave={release}
		/>
	);
}

function currentOffset(node: HTMLElement) {
	const read = (name: string) => Number.parseFloat(node.style.getPropertyValue(name)) || 0;
	return { x: read("--_btn-mx"), y: read("--_btn-my") };
}

/**
 * How far a magnetic button leans toward the pointer: the pointer's distance from the button's
 * centre, scaled by `strength`. 0 stays put, 1 would put the centre under the pointer.
 */
export function magneticOffset(
	rect: { left: number; top: number; width: number; height: number },
	clientX: number,
	clientY: number,
	strength: number,
) {
	return {
		x: (clientX - (rect.left + rect.width / 2)) * strength,
		y: (clientY - (rect.top + rect.height / 2)) * strength,
	};
}

"use client";

import { Button, type ButtonProps } from "./button";
import { buttonParts } from "./button.styles";
import { cn } from "@/lib/utils";

export type MetallicButtonProps = Omit<ButtonProps, "variant" | "ripple"> & {
	/** Holds the chrome still; the rim keeps its polish. */
	paused?: boolean;
};

/**
 * A Button with a polished chrome rim. The rim's gradient drifts on a slow loop and hovering
 * sweeps a highlight across it, both in CSS. The face is the page color, so the label reads as
 * on a ghost button.
 */
export function MetallicButton({ paused, children, className, ...rest }: MetallicButtonProps) {
	return (
		<Button
			{...(rest as ButtonProps)}
			variant="ghost"
			className={cn("rx-btn-metal", className)}
			data-paused={paused ? "" : undefined}
		>
			<span className={buttonParts.metalRim} aria-hidden="true" />
			<span className={buttonParts.metalSheen} aria-hidden="true" />
			<span className={buttonParts.metalFace} aria-hidden="true" />
			<span className={buttonParts.metalBevel} aria-hidden="true" />
			{children}
		</Button>
	);
}

"use client";

import {
	type CSSProperties,
	type ReactNode,
	type Ref,
	useEffect,
	useLayoutEffect,
	useRef,
	useState,
} from "react";
import { Button, type ButtonProps } from "./button";
import { type ButtonState, buttonParts } from "./button.styles";
import { exitMs, splitLetters } from "./stateful-label";

export type StatefulButtonProps = ButtonProps & {
	/** `loading` blocks clicks and marks the button busy; the others only change the label. */
	state?: ButtonState;
	/** The idle label. */
	children: ReactNode;
	loadingText?: ReactNode;
	successText?: ReactNode;
	errorText?: ReactNode;
	/** An icon after the idle label. It folds away while any other state shows. */
	icon?: ReactNode;
};

const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/**
 * A button for an action that takes a moment. Changing `state` folds the old status icon away,
 * widens the new one in, and rolls the label over letter by letter while the button eases to the
 * new width. All of that is CSS; this component only says which label is arriving and which is
 * leaving, and measures the arriving one.
 */
export function StatefulButton({
	state = "idle",
	children,
	loadingText = "Loading",
	successText = "Done",
	errorText = "Try again",
	icon,
	onClick,
	...rest
}: StatefulButtonProps) {
	const busy = state === "loading";
	const text = { idle: children, loading: loadingText, success: successText, error: errorText }[
		state
	];

	return (
		<Button
			{...rest}
			aria-busy={busy || undefined}
			aria-live="polite"
			data-state={state}
			onClick={(event) => (busy ? event.preventDefault() : onClick?.(event))}
		>
			<Slot shown={state === "loading"}>
				<span className={buttonParts.glyph} data-glyph="spinner" />
			</Slot>
			<Slot shown={state === "success"}>
				<span className={buttonParts.glyph} data-glyph="check" />
			</Slot>
			<Slot shown={state === "error"}>
				<span className={buttonParts.glyph} data-glyph="cross" />
			</Slot>
			<LabelSwap id={state}>{text}</LabelSwap>
			{icon ? <Slot shown={state === "idle"}>{icon}</Slot> : null}
		</Button>
	);
}

function Slot({ shown, children }: { shown: boolean; children: ReactNode }) {
	return (
		<span className={buttonParts.slot} data-shown={shown ? "" : undefined} aria-hidden="true">
			{children}
		</span>
	);
}

type Shown = { id: string; node: ReactNode; enter: boolean };

/**
 * One label at a time, plus the one leaving. A new `id` (or new text) keeps the old label for the
 * length of its exit, marks the new one to roll in, and sets the box width to the new label's.
 * The first render does not animate.
 */
function LabelSwap({ id, children }: { id: string; children: ReactNode }) {
	const key =
		typeof children === "string" || typeof children === "number" ? `${id}:${children}` : id;
	const [shown, setShown] = useState<Shown>({ id: key, node: children, enter: false });
	const [leaving, setLeaving] = useState<Shown[]>([]);
	const [width, setWidth] = useState<number>();
	// The keyed `<Label>` below remounts per label, so its roll-in keyframes start over each swap.
	const current = useRef<HTMLSpanElement>(null);

	if (shown.id !== key) {
		setLeaving((list) => [...list.filter((item) => item.id !== key), { ...shown, enter: false }]);
		setShown({ id: key, node: children, enter: true });
	}

	// Measure the letters as laid out, not the plain string: kerning can make the string narrower
	// than its inline-block letters, which would clip the last one.
	useIsomorphicLayoutEffect(() => {
		const next = current.current?.offsetWidth;
		if (next) setWidth((before) => (before === next ? before : next));
	});

	useEffect(() => {
		if (leaving.length === 0) return;
		const longest = Math.max(...leaving.map((item) => letterCount(item.node)));
		const timer = setTimeout(() => setLeaving([]), exitMs(longest) + 40);
		return () => clearTimeout(timer);
	}, [leaving]);

	return (
		<span
			className={buttonParts.text}
			style={width ? ({ "--_btn-text-w": `${width}px` } as CSSProperties) : undefined}
		>
			{typeof children === "string" ? <span className={buttonParts.srOnly}>{children}</span> : null}
			<Label key={shown.id} ref={current} node={children} enter={shown.enter} />
			{leaving.map((item) => (
				<Label key={`out:${item.id}`} node={item.node} exit />
			))}
		</span>
	);
}

function letterCount(node: ReactNode): number {
	return typeof node === "string" ? splitLetters(node).length : 1;
}

function Label({
	node,
	enter,
	exit,
	ref,
}: {
	node: ReactNode;
	enter?: boolean;
	exit?: boolean;
	ref?: Ref<HTMLSpanElement>;
}) {
	const text = typeof node === "string";
	return (
		<span
			ref={ref}
			className={buttonParts.label}
			data-enter={enter ? "" : undefined}
			data-exit={exit ? "" : undefined}
			aria-hidden={text || exit ? "true" : undefined}
		>
			{text ? (
				splitLetters(node).map((letter, index) => (
					<span
						// Position is the letter's identity within one label.
						// oxlint-disable-next-line react/no-array-index-key
						key={index}
						className={buttonParts.letter}
						style={{ "--_i": index } as CSSProperties}
					>
						{letter}
					</span>
				))
			) : (
				<span className={buttonParts.letter}>{node}</span>
			)}
		</span>
	);
}

/**
 * The letters a label rolls in as. Split by code point so an emoji or accented letter stays whole,
 * and a space keeps its width once it sits in its own inline-block.
 */
export function splitLetters(text: string): string[] {
	return Array.from(text);
}

/** How long a leaving label needs before it can be removed: the last letter's delay plus 160ms. */
export function exitMs(letters: number): number {
	return 160 + Math.max(0, letters - 1) * 12.5;
}

"use client";

import {
	type CSSProperties,
	type PointerEvent,
	type PointerEventHandler,
	type ReactNode,
	useRef,
	useState,
} from "react";
import { type ButtonSize, type ButtonVariant, buttonClass, buttonParts } from "./button.styles";
import { cn } from "@/lib/utils";

export type ButtonLookProps = {
	variant?: ButtonVariant;
	size?: ButtonSize;
	/** Scale while pressed. 1 turns the press off. Default 0.93. */
	pressScale?: number;
	/** A soft disc spreads from where the button was pressed. */
	ripple?: boolean;
};

type Ripple = { id: number; x: number; y: number; d: number };

/** Whether the user or an ancestor asked for no motion. Ripples are skipped then, not hidden. */
export function motionReduced(node: Element): boolean {
	if (node.closest('[data-motion="off"]')) return true;
	return typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/**
 * Where a ripple starts and how big it grows: centred on the press, and twice the longer side so
 * it covers the button from any corner.
 */
export function ripplePlacement(
	rect: { left: number; top: number; width: number; height: number },
	clientX: number,
	clientY: number,
) {
	return {
		x: clientX - rect.left,
		y: clientY - rect.top,
		d: Math.max(rect.width, rect.height) * 2,
	};
}

/** The class, style, ripple layer and pointer handler every button element shares. */
export function useButtonLook<E extends HTMLElement>(
	{ variant, size, pressScale, ripple }: ButtonLookProps,
	{
		look,
		className,
		style,
		onPointerDown,
	}: {
		look?: "magnetic" | "metallic";
		className?: string;
		style?: CSSProperties;
		onPointerDown?: PointerEventHandler<E>;
	},
): {
	className: string;
	style: CSSProperties | undefined;
	onPointerDown: PointerEventHandler<E>;
	ripples: ReactNode;
} {
	const [ripples, setRipples] = useState<Ripple[]>([]);
	const nextId = useRef(0);

	const handlePointerDown = (event: PointerEvent<E>) => {
		onPointerDown?.(event);
		if (!ripple || event.button !== 0 || motionReduced(event.currentTarget)) return;
		const placed = ripplePlacement(
			event.currentTarget.getBoundingClientRect(),
			event.clientX,
			event.clientY,
		);
		const id = nextId.current++;
		setRipples((current) => [...current, { id, ...placed }]);
	};

	return {
		className: cn(buttonClass({ variant, size, look }), className),
		style:
			pressScale === undefined
				? style
				: ({ ...style, "--_btn-press": String(pressScale) } as CSSProperties),
		onPointerDown: handlePointerDown,
		ripples: ripple ? (
			<span className={buttonParts.ripples} aria-hidden="true">
				{ripples.map(({ id, x, y, d }) => (
					<span
						key={id}
						className={buttonParts.ripple}
						style={
							{
								"--_ripple-x": `${x}px`,
								"--_ripple-y": `${y}px`,
								"--_ripple-d": `${d}px`,
							} as CSSProperties
						}
						onAnimationEnd={() => setRipples((current) => current.filter((r) => r.id !== id))}
					/>
				))}
			</span>
		) : null,
	};
}
